<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Могут ли приставы арестовать лицевой счёт в казначействе?", "acceptedAnswer": {"@type": "Answer", "text": "Напрямую — нет. Постановления об аресте и списании по ст. 70 и 81 Закона № 229-ФЗ адресованы банкам и иным кредитным организациям, а лицевой счёт открыт в ТОФК без договора банковского счёта. Взыскание идёт по другому имуществу: банковским счетам, дебиторке, активам."}}, {"@type": "Question", "name": "Может ли налоговая выставить инкассо к лицевому счёту?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Взыскание по ст. 46 НК и блокировка по ст. 76 НК применяются к счетам в банках, открытым по договору банковского счёта (п. 2 ст. 11 НК). Лицевой счёт в казначействе под это определение не подпадает. Недоимку ФНС взыскивает с банковских счетов и за счёт иного имущества по ст. 47 НК."}}, {"@type": "Question", "name": "Блокировка расчётных счетов останавливает работу по контракту?", "acceptedAnswer": {"@type": "Answer", "text": "Как правило, нет: лицевой счёт продолжает работать, и платежи в рамках контракта — поставщикам, на зарплату, налоги — проходят санкционирование независимо от блокировок в банках. Критичные расчёты стоит перевести в казначейский контур."}}, {"@type": "Question", "name": "Можно ли спрятать деньги от кредиторов на лицевом счёте?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Во-первых, на лицевой счёт попадают только целевые средства по контракту, и посторонние платежи через него не пройдут. Во-вторых, прибыль и возмещение всё равно выводятся на расчётный счёт, где доступны взысканию. Казначейское сопровождение — инструмент контроля бюджетных денег, а не защиты активов."}}, {"@type": "Question", "name": "Могут ли взыскать дебиторскую задолженность по госконтракту?", "acceptedAnswer": {"@type": "Answer", "text": "Ст. 75–76 Закона № 229-ФЗ допускают обращение взыскания на дебиторскую задолженность. При казначейском сопровождении конструкция сталкивается с обязанностью заказчика платить на лицевой счёт, и практика разрешения этой коллизии неоднородна — но арест права требования возможен и способен осложнить расчёты."}}, {"@type": "Question", "name": "Что происходит с деньгами на отдельном счёте по гособоронзаказу при долгах?", "acceptedAnswer": {"@type": "Answer", "text": "Ст. 8.4 Закона № 275-ФЗ запрещает исполнение исполнительных документов по отдельному счёту, кроме трёх случаев: возмещение вреда жизни и здоровью, выходные пособия и оплата труда работников, взыскание в доход РФ. Остальные долги с отдельного счёта не списываются, пока действует режим."}}, {"@type": "Question", "name": "Снимается ли защита после исполнения контракта?", "acceptedAnswer": {"@type": "Answer", "text": "Да. После завершения казначейского сопровождения и закрытия лицевого счёта (или снятия режима отдельного счёта) средства, причитающиеся исполнителю, переходят в обычный оборот — на расчётном счёте они доступны взысканию в общем порядке."}}, {"@type": "Question", "name": "Что будет со средствами на лицевом счёте при банкротстве исполнителя?", "acceptedAnswer": {"@type": "Answer", "text": "Целевые средства не превращаются в конкурсную массу: неотработанный аванс возвращается заказчику при расторжении контракта. В массу попадает то, что причитается исполнителю за принятые работы. Само возбуждение дела о банкротстве — основание мер казначейского мониторинга вплоть до приостановления операций."}}, {"@type": "Question", "name": "Чем арест приставами отличается от приостановления операций казначейством?", "acceptedAnswer": {"@type": "Answer", "text": "Это разные механизмы. Арест — мера исполнительного производства по долгам компании, к лицевому счёту напрямую не применяется. Приостановление операций — мера реагирования самого казначейства по итогам мониторинга (ст. 242.13-1 БК, Правила № 2483); она бьёт по счёту непосредственно и опаснее для исполнения контракта."}}, {"@type": "Question", "name": "Видят ли приставы и налоговая лицевой счёт компании?", "acceptedAnswer": {"@type": "Answer", "text": "Лицевые счета в ТОФК не входят в систему банковских запросов ФНС и приставов. Но само наличие контракта — публичная информация (реестр контрактов в ЕИС), поэтому взыскатели узнают о будущих поступлениях и работают с дебиторкой и расчётными счетами."}}, {"@type": "Question", "name": "Заказчик может не платить на лицевой счёт, сославшись на арест?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Обязанность заказчика платить в порядке, установленном контрактом и бюджетным законодательством, сохраняется. Коллизии с постановлениями приставов о дебиторке разрешаются в правовом поле — в одностороннем порядке менять получателя или удерживать оплату заказчик не вправе."}}, {"@type": "Question", "name": "Как кредитору реально взыскать долг с подрядчика на казначейском сопровождении?", "acceptedAnswer": {"@type": "Answer", "text": "Работать по классике: исполнительные листы на банковские счета, арест имущества, взыскание на дебиторскую задолженность, контроль вывода прибыли из казначейского контура. Гнаться за самим лицевым счётом бесперспективно — деньги ловят на входе в банк."}}]}
</script>
<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "HowTo", "name": "Что делать исполнителю контракта при арестах и блокировках счетов", "inLanguage": "ru-RU", "step": [{"@type": "HowToStep", "position": 1, "name": "Составить карту счетов и взысканий", "text": "Свести в одну таблицу все счета компании (лицевой в ТОФК, отдельный в уполномоченном банке, расчётные в банках) и все действующие взыскания: инкассо, блокировки, постановления приставов, стадии исполнительных производств."}, {"@type": "HowToStep", "position": 2, "name": "Обеспечить исполнение контракта через лицевой счёт", "text": "Перевести критичные для контракта расчёты в казначейский контур: платежи поставщикам по контракту, зарплата, налоги проходят санкционирование независимо от блокировок банковских счетов."}, {"@type": "HowToStep", "position": 3, "name": "Проверить законность взысканий", "text": "Сверить каждое постановление и решение с законом: арест средств, взыскание на которые не допускается, обжалуется в порядке подчинённости и в суде (гл. 18 Закона № 229-ФЗ), решения налогового органа — через вышестоящий орган."}, {"@type": "HowToStep", "position": 4, "name": "Урегулировать долги до вывода прибыли", "text": "Реструктурировать недоимку и договориться с кредиторами о графике до перечисления прибыли на расчётный счёт — иначе выведенные средства уйдут по инкассо в момент зачисления."}, {"@type": "HowToStep", "position": 5, "name": "Отслеживать триггеры мониторинга", "text": "Контролировать основания мер реагирования казначейского мониторинга (банкротное заявление, реестры, признаки нарушений) — приостановление операций казначейством опаснее для контракта, чем действия приставов."}]}
</script>
