{"@context": "https://schema.org", "@type": "DefinedTermSet", "name": "Термины: арест и взыскание средств на лицевом счёте", "inLanguage": "ru-RU", "hasDefinedTerm": [{"@type": "DefinedTerm", "name": "Лицевой счёт участника казначейского сопровождения", "description": "Счёт, открываемый ТОФК исполнителю контракта для учёта операций с целевыми средствами (ст. 242.23 БК, приказ ФК № 44н); договором банковского счёта не оформляется."}, {"@type": "DefinedTerm", "name": "Арест денежных средств", "description": "Мера обеспечения исполнения: прекращение расходных операций по счёту в пределах арестованной суммы (ст. 81 Закона № 229-ФЗ) — адресована банкам и иным кредитным организациям."}, {"@type": "DefinedTerm", "name": "Инкассовое поручение", "description": "Расчётный документ на бесспорное списание средств со счёта в банке — инструмент взыскания налоговой недоимки по ст. 46 НК РФ."}, {"@type": "DefinedTerm", "name": "Дебиторская задолженность", "description": "Право требования должника к третьим лицам (например, оплата по контракту); имущественное право, на которое обращается взыскание по ст. 75–76 Закона № 229-ФЗ."}, {"@type": "DefinedTerm", "name": "Казначейский мониторинг", "description": "Проверка участников казначейского сопровождения на признаки финансовых нарушений с мерами реагирования вплоть до приостановления операций (ст. 242.13-1 БК, Правила № 2483)."}, {"@type": "DefinedTerm", "name": "Отдельный счёт (гособоронзаказ)", "description": "Счёт головного исполнителя или исполнителя в уполномоченном банке с закрытым режимом операций по ст. 8.3–8.4 Закона № 275-ФЗ."}, {"@type": "DefinedTerm", "name": "Конкурсная масса", "description": "Всё имущество должника-банкрота, предназначенное для расчётов с кредиторами (ст. 131 Закона № 127-ФЗ); целевые средства на исполнение контракта в неё по общему правилу не попадают."}]}
